ENR[8] = {
 'Grande Divergence : charbon et empire': {
  'af': "Pomeranz soutient que l'avance industrielle britannique ne s'explique pas par une supériorité institutionnelle, culturelle ou scientifique ancienne, mais par deux avantages largement contingents : la proximité de gisements de charbon et l'accès aux ressources du Nouveau Monde. Sa thèse commence par un constat comparatif : vers 1750, les régions les plus développées d'Europe et de Chine — l'Angleterre et le delta du Yangzi — présentaient des niveaux de vie, de commercialisation et de productivité agricole comparables. L'explication de la divergence ne peut donc pas se trouver dans une supériorité européenne préexistante. Pomeranz identifie la contrainte commune à toutes les économies organiques avancées : la terre devait fournir simultanément nourriture, combustible, fibres textiles et matériaux de construction. Le charbon lève la contrainte énergétique sans mobiliser de surface, et les colonies lèvent la contrainte agricole en fournissant l'équivalent de millions d'hectares virtuels.",
  'po': "Dans le chapitre, cette thèse fournit l'explication matérielle de la révolution industrielle, concurrente de l'explication institutionnelle de North et d'Acemoglu, et elle écarte toute lecture eurocentrée de l'industrialisation. Elle montre qu'un même niveau de développement peut déboucher sur des trajectoires opposées selon des conditions géologiques et impériales.",
  'co': "Kenneth Pomeranz explique la Grande Divergence par deux avantages contingents : des gisements de charbon proches des centres manufacturiers et l'accès aux ressources coloniales, qui ont permis à l'Angleterre de franchir la contrainte foncière où le delta du Yangzi, d'un développement comparable, est resté enfermé.",
 },
 'Prix relatifs : salaires élevés et énergie bon marché': {
  'af': "Allen soutient que la mécanisation est devenue rentable en Angleterre, et seulement là, parce que la structure des prix y était unique : des salaires élevés et une énergie très bon marché rendaient avantageux de remplacer le travail par des machines consommant du charbon. La thèse repose sur un principe simple et exigeant : une innovation n'est adoptée que si elle est profitable aux prix en vigueur, et non parce qu'elle est techniquement supérieure. Une machine remplace du travail et consomme du capital et de l'énergie. Là où les salaires sont bas et le charbon cher — en France, en Inde, en Chine — elle n'est pas rentable, même lorsqu'elle est parfaitement connue. Là où les salaires sont hauts et le charbon à peine extrait du sol voisin, elle l'est. L'invention devient ainsi une réponse économique rationnelle à un rapport de prix : la demande de technique précède et commande l'offre de technique.",
  'po': "Dans le chapitre, cette analyse endogénéise le progrès technique dans l'explication de la révolution industrielle : l'innovation n'est plus un événement extérieur mais une décision économique. Elle écarte les explications par le génie national ou par la culture, et fournit un raisonnement transposable à toutes les questions d'adoption technologique, y compris contemporaines.",
  'co': "Robert Allen explique la mécanisation anglaise par les prix relatifs : des salaires élevés et un charbon très bon marché rendaient rentable le remplacement du travail par la machine, alors que la même technique, pourtant connue, ne l'était pas là où les salaires étaient bas et l'énergie chère.",
 },
 'La machine à vapeur comme symbole et comme technique': {
  'af': "Le perfectionnement de la machine à vapeur, breveté par Watt en 1769, fournit pour la première fois une source d'énergie mécanique affranchie du vent, du cours d'eau et de la force animale, mais l'industrialisation ne saurait s'y réduire. L'apport technique décisif est le condenseur séparé, qui évite de refroidir le cylindre à chaque cycle et abaisse considérablement la consommation de charbon. La machine devient alors utilisable loin des mines, ce qui libère l'implantation des usines de la contrainte hydraulique et autorise la concentration urbaine de la production. Il faut cependant mesurer la portée exacte de l'innovation : elle n'a d'effet qu'articulée au charbon, au textile mécanisé, au chemin de fer et à l'organisation en usine. C'est un système technique, et non une invention isolée, qui fait une révolution industrielle — la confusion inverse étant l'erreur la plus courante sur ce sujet.",
  'po': "Dans le chapitre, cet exemple sert à introduire la première révolution industrielle tout en imposant d'emblée la nuance méthodologique attendue : une révolution industrielle n'est pas une invention mais une convergence d'innovations complémentaires, de ressources et d'une organisation du travail.",
  'co': "Le brevet de Watt (1769) et son condenseur séparé rendent la machine à vapeur utilisable loin des mines, affranchissant l'usine de la contrainte hydraulique : l'industrialisation ne se réduit pas pour autant à cette invention, mais résulte d'un système technique associant énergie, mécanisation textile, transport et organisation.",
 },
 'Spinning Jenny et mécanisation du filage': {
  'af': "La Spinning Jenny, mise au point par Hargreaves en 1764, permet à un seul ouvrier d'actionner plusieurs broches simultanément et multiplie ainsi la productivité du filage. Son intérêt analytique dépasse la performance technique : elle illustre le caractère séquentiel et cumulatif des innovations. Le textile était en effet contraint par un déséquilibre interne, le tissage consommant plus de fil que le filage manuel n'en pouvait produire. La Jenny lève ce goulet d'étranglement mais en déplace aussitôt la contrainte : l'augmentation de la production de fil accroît la demande de coton brut, ce qui reporte la tension en amont, vers la culture du coton et son approvisionnement colonial. Une innovation en appelle ainsi une autre, non par une dynamique abstraite du progrès, mais parce qu'elle crée des déséquilibres que les innovations suivantes viennent résoudre.",
  'po': "Dans le chapitre, cet exemple illustre concrètement la notion de grappe d'innovation : les innovations textiles s'enchaînent parce que chacune crée le déséquilibre que la suivante résout. Il montre aussi que la révolution industrielle anglaise est indissociable de son approvisionnement colonial en matières premières.",
  'co': "La Spinning Jenny de Hargreaves (1764) multiplie les broches actionnées par un seul ouvrier et lève le goulet d'étranglement du filage, mais en déplace aussitôt la contrainte vers l'approvisionnement en coton brut : chaque innovation crée le déséquilibre que la suivante vient résoudre.",
 },
 "Water Frame et naissance de l'usine": {
  'af': "L'apport d'Arkwright ne se réduit pas à une innovation technique : en concevant en 1769 une machine actionnée par la force hydraulique, trop lourde et trop coûteuse pour un atelier domestique, il rend nécessaire la concentration des ouvriers dans un même lieu. La thèse est que la transformation technique engendre une transformation sociale du travail. Tant que les machines étaient actionnables à la main, la production pouvait rester dispersée au domicile des ouvriers, selon le domestic system : le travailleur possédait ses outils, organisait son temps et était payé à la pièce. Une machine mue par une roue hydraulique impose en revanche un site fixe, un investissement important, donc un propriétaire du capital qui rassemble la main-d'œuvre, fixe les horaires et surveille la cadence. Le factory system naît ainsi d'une contrainte technique, et avec lui le salariat, la discipline d'usine et la séparation du domicile et du lieu de travail.",
  'po': "Dans le chapitre, cet exemple articule les deux grandes questions traitées — l'industrialisation et la transformation du travail — en montrant qu'elles ne sont pas juxtaposées mais liées causalement. Il fournit l'origine historique du rapport salarial dont le chapitre étudiera ensuite les transformations.",
  'co': "Avec la Water Frame (1769), Arkwright impose une machine trop lourde pour l'atelier domestique : le passage du domestic system au factory system fait naître de cette contrainte technique le salariat, la discipline horaire et la séparation du domicile et du lieu de travail.",
 },
 'Mule et finesse du fil': {
  'af': "La mule-jenny, mise au point par Crompton en 1779, combine les principes des deux machines antérieures pour produire un fil à la fois fin et résistant, ce qui ouvre au coton anglais le marché des textiles de qualité. La thèse illustre un mécanisme d'innovation par combinaison : la Jenny produisait un fil fin mais fragile, la Water Frame un fil solide mais grossier ; en associant les deux mouvements, Crompton obtient un fil adapté aux tissus fins jusque-là importés d'Inde. La conséquence est commerciale autant que technique, et considérable : l'Angleterre cesse d'importer des cotonnades indiennes pour en exporter, y compris vers l'Inde elle-même, ce qui désorganise une industrie textile indienne jusqu'alors dominante. Un gain de qualité technique suffit ainsi à renverser un courant d'échange séculaire.",
  'po': "Dans le chapitre, cet exemple montre que les innovations se combinent au lieu de se succéder simplement, et établit le lien entre révolution industrielle et renversement des rapports commerciaux internationaux. Il fournit un cas historique de désindustrialisation provoquée par la concurrence, utile bien au-delà de ce chapitre.",
  'co': "La mule de Crompton (1779) combine finesse et solidité du fil et permet à l'Angleterre de substituer ses cotonnades aux importations indiennes, puis de les exporter vers l'Inde : un gain de qualité technique suffit à renverser un courant d'échange séculaire.",
 },
 'Power Loom et mécanisation du tissage': {
  'af': "Le métier à tisser mécanique de Cartwright, en 1785, achève la mécanisation de la filière textile en portant la machine sur la dernière opération restée manuelle. La thèse en tire deux conséquences d'inégale notoriété. La première est productive : le filage mécanisé avait créé un excès de fil que le tissage à la main ne pouvait absorber ; le métier mécanique lève ce goulet et permet d'intégrer toute la filière dans une même usine, sous une même source d'énergie. La seconde est sociale et brutale : le tissage à la main était un métier qualifié et bien rémunéré, exercé par des artisans indépendants. Sa mécanisation déclasse en une génération une catégorie professionnelle entière, dont les revenus s'effondrent sans qu'aucune reconversion équivalente ne soit disponible. C'est à ce déclassement, et non à une hostilité de principe envers la technique, que répondent les mouvements de destruction de machines.",
  'po': "Dans le chapitre, cet exemple fournit le cas historique le plus net de destruction effective et durable d'un métier qualifié par le progrès technique. Il permet d'évaluer concrètement la thèse du déversement : l'emploi a bien été recréé ailleurs, mais au prix d'une génération sacrifiée, ce qui est précisément l'objet du débat contemporain sur l'automatisation.",
  'co': "Le Power Loom de Cartwright (1785) mécanise le tissage et permet l'intégration de toute la filière textile en usine, mais il déclasse en une génération les tisserands à la main, artisans qualifiés dont l'effondrement des revenus explique les mouvements de destruction de machines.",
 },
 'Vaccination et recul de la mortalité': {
  'af': "La mise au point de la vaccination contre la variole par Jenner en 1797 établit que le progrès médical, et non seulement l'enrichissement, constitue une cause majeure du recul de la mortalité. La thèse a une portée économique précise. La variole comptait parmi les premières causes de mortalité, singulièrement infantile ; son recul abaisse la mortalité indépendamment du niveau de vie des populations concernées. Deux conséquences économiques en découlent. La première est démographique : la baisse de la mortalité précède celle de la natalité et déclenche la phase de forte croissance de la population qui caractérise la transition démographique. La seconde est productive : une population en meilleure santé travaille plus longtemps, s'absente moins et accumule davantage de capital humain, ce qui relie directement la santé à la productivité.",
  'po': "Dans le chapitre, cet exemple montre que l'industrialisation s'accompagne de transformations démographiques et sanitaires qui en sont à la fois la condition et la conséquence. Il relie la révolution industrielle à la transition démographique étudiée au chapitre 7 et introduit la santé comme composante du capital humain.",
  'co': "La vaccination contre la variole mise au point par Jenner en 1797 fait reculer la mortalité indépendamment du niveau de vie : elle déclenche la première phase de la transition démographique et améliore le capital humain, reliant ainsi progrès médical et productivité.",
 },
 'Droits de propriété et investissement industriel': {
  'af': "North soutient que l'industrialisation exige des engagements de capital longs et largement irréversibles, et qu'elle ne se produit donc que là où des institutions crédibles garantissent que le rendement futur ne sera pas confisqué. La thèse souligne le rôle des transformations institutionnelles anglaises de la fin du XVIIᵉ siècle : limitation du pouvoir arbitraire de la Couronne, sécurisation de la dette publique, prévisibilité des tribunaux, protection des brevets. Ces règles réduisent le risque politique, abaissent le taux auquel les entrepreneurs escomptent l'avenir et rendent rationnel l'investissement dans des équipements amortis sur plusieurs décennies. L'argument est explicitement comparatif : d'autres économies, techniquement capables mais politiquement arbitraires, n'ont pas franchi le pas, non faute de savoir, mais faute de garantie.",
  'po': "Dans le chapitre, cette thèse fournit l'explication institutionnelle de la révolution industrielle et s'oppose frontalement aux explications matérielles de Pomeranz et d'Allen. Le débat entre ces deux familles d'explication constitue l'axe de discussion le plus riche du chapitre, car il ne s'agit pas d'une querelle de détail mais de deux conceptions de la causalité historique.",
  'co': "Douglass North explique l'industrialisation anglaise par la crédibilité institutionnelle : la limitation du pouvoir arbitraire, la sécurité des contrats et la protection des brevets abaissent le risque politique et rendent rationnel l'investissement dans des équipements amortis sur plusieurs décennies.",
 },
 'Institutions inclusives et direction du progrès technique': {
  'ti': 'Institutions inclusives et autorisation de la destruction créatrice',
  'af': "Acemoglu soutient que des institutions inclusives sont la condition politique du progrès technique, parce qu'elles seules autorisent la destruction créatrice. La thèse articule institutions et innovation par un argument d'économie politique : toute innovation majeure dévalorise des actifs existants et crée des entrants qui menacent les positions acquises. Dans un régime où le pouvoir politique est concentré entre les mains de ceux qui détiennent ces positions, il est rationnel pour eux d'empêcher l'innovation, même lorsqu'elle accroîtrait la richesse nationale : la perte de rente l'emporte, pour eux, sur le gain collectif. Des institutions inclusives, qui répartissent largement le pouvoir politique, privent l'élite de ce droit de veto et rendent possible le renouvellement. Acemoglu établit ainsi que le niveau d'innovation d'une société n'est pas une donnée technique mais le résultat d'un équilibre politique.",
  'po': "Dans le chapitre, cette thèse relie l'analyse institutionnelle à la destruction créatrice de Schumpeter et explique pourquoi certaines sociétés techniquement avancées n'ont pas industrialisé : non par incapacité, mais parce que ceux qui détenaient le pouvoir avaient intérêt à l'empêcher. Elle fait du politique une variable de l'analyse de l'innovation.",
  'co': "Daron Acemoglu montre que les institutions inclusives sont la condition politique de la destruction créatrice : en répartissant le pouvoir, elles privent les détenteurs de rentes du droit de veto qui leur permettrait de bloquer une innovation menaçant leur position.",
 },
 "Institutions, élites et blocage de l'innovation": {
  'af': "Robinson soutient qu'une élite qui tire sa richesse d'une rente a intérêt à bloquer les innovations menaçant sa position, même lorsqu'elles accroîtraient la richesse nationale, et que ce blocage explique des retards technologiques autrement incompréhensibles. La thèse repose sur un calcul rationnel qu'il convient d'énoncer précisément : l'innovation redistribue le pouvoir économique, elle crée des entrants et dévalorise des actifs ; une élite qui contrôle à la fois l'économie et l'État peut donc interdire, taxer ou retarder la nouveauté, et elle a raison de le faire du point de vue de son propre intérêt. Le résultat est que des sociétés disposant des mêmes connaissances techniques ont connu des destins opposés. Le retard technologique apparaît alors comme un choix politique et non comme une incapacité, ce qui déplace radicalement la question de l'innovation.",
  'po': "Dans le chapitre, cette analyse complète celle d'Acemoglu en montrant le mécanisme concret du blocage et explique pourquoi la diffusion des techniques n'est pas automatique. Elle fournit une réponse au paradoxe de sociétés savantes restées non industrielles, et rejoint par ce biais le débat avec Pomeranz.",
  'co': "James Robinson montre que le retard technologique peut être un choix politique : une élite tirant sa richesse d'une rente a intérêt à interdire ou retarder les innovations qui créeraient des entrants et dévaloriseraient ses actifs, même au détriment de la richesse nationale.",
 },
 'Décollage industriel britannique': {
  'af': "Appliquée au cas britannique, l'analyse de Rostow soutient que l'industrialisation constitue le prototype du décollage : le franchissement d'un seuil d'investissement et l'action de secteurs moteurs font basculer la croissance dans un régime auto-entretenu. Le modèle identifie le textile puis le chemin de fer comme secteurs moteurs : leur expansion appelle du charbon, du fer, des machines, des capitaux et de la main-d'œuvre, et diffuse ainsi la croissance par des effets d'entraînement en amont et en aval. Au-delà d'un certain taux d'investissement, la croissance cesse de dépendre d'impulsions extérieures et s'alimente elle-même. La portée du modèle est descriptive plutôt qu'explicative, et c'est la limite qu'il faut savoir énoncer : il nomme avec précision un basculement sans expliquer pourquoi il s'est produit en Angleterre et pas ailleurs.",
  'po': "Dans le chapitre, ce modèle fournit un vocabulaire utile pour caractériser le basculement industriel — seuil d'investissement, secteurs moteurs, effets d'entraînement — et ouvre, par son silence sur les causes, la discussion avec Pomeranz, Allen et North. Il montre qu'une bonne description n'est pas une explication.",
  'co': "Appliqué à l'Angleterre, le modèle de Rostow caractérise le décollage par le franchissement d'un seuil d'investissement et l'action de secteurs moteurs — textile puis chemin de fer — dont les effets d'entraînement diffusent la croissance, sans toutefois expliquer pourquoi ce basculement a eu lieu là plutôt qu'ailleurs.",
 },
 "Entrepreneur, grappes d'innovation et cycles longs": {
  'ti': "L'entrepreneur innovateur, agent du changement économique",
  'af': "Schumpeter soutient que le moteur du changement économique n'est ni l'épargnant ni le gestionnaire mais l'entrepreneur, défini non par la propriété du capital mais par une fonction : introduire économiquement une nouveauté. La thèse repose sur une distinction rigoureuse entre l'invention, qui relève de la technique ou de la science, et l'innovation, qui est son introduction effective dans le circuit économique. Schumpeter en recense cinq formes : un produit nouveau, un procédé nouveau, un marché nouveau, une source d'approvisionnement nouvelle, une organisation nouvelle. L'entrepreneur se caractérise par sa capacité à briser la routine et à affronter une incertitude non probabilisable, ce qui le distingue du capitaliste qui prête et du manager qui administre. Le crédit bancaire joue un rôle décisif dans ce schéma : il lui permet de détourner des ressources de leurs usages établis avant même d'avoir produit quoi que ce soit.",
  'po': "Dans le chapitre, cette analyse fournit la figure centrale autour de laquelle s'organise la question « qui dirige l'entreprise ? » : l'entrepreneur schumpétérien sera successivement contesté par le manager de Berle et Means, par la technostructure de Galbraith et par la déconstruction de Galluzzo. Elle introduit en outre le rôle du financement dans l'innovation.",
  'co': "Schumpeter définit l'entrepreneur par une fonction et non par la propriété du capital : introduire économiquement une nouveauté — produit, procédé, marché, approvisionnement ou organisation — en brisant la routine, le crédit bancaire lui permettant de détourner des ressources de leurs usages établis.",
 },
 'Organisation scientifique du travail': {
  'af': "Taylor soutient que la productivité peut être considérablement accrue en retirant à l'ouvrier la conception de son travail pour la confier à un bureau des méthodes, la manière de faire devant être étudiée, chronométrée puis prescrite. La thèse repose sur quatre opérations solidaires. La division verticale sépare la conception, confiée aux ingénieurs, de l'exécution, laissée à l'ouvrier : c'est l'opération décisive, car elle prive celui-ci de son savoir-faire, donc de son pouvoir de négociation sur la cadence. La division horizontale décompose la tâche en gestes élémentaires. Le chronométrage détermine la meilleure façon de faire et le temps alloué. Le salaire au rendement aligne l'intérêt de l'ouvrier sur la cadence prescrite. La logique d'ensemble est celle d'une appropriation par l'organisation d'un savoir qui appartenait au métier, ce qui explique que la résistance ouvrière ne soit pas de l'irrationalité mais la défense d'une maîtrise.",
  'po': "Dans le chapitre, cette analyse fournit le premier modèle productif systématique et le point de départ de l'étude de l'organisation du travail. Elle permet d'articuler gains de productivité et transformation du rapport salarial, et constitue la référence que Mayo, puis Ohno, contesteront chacun à leur manière.",
  'co': "L'organisation scientifique du travail de Taylor (1911) repose sur la division verticale, qui retire à l'ouvrier la conception de son travail, la division horizontale, le chronométrage et le salaire au rendement : elle accroît la productivité en s'appropriant le savoir-faire ouvrier.",
 },
 'Fordisme : production et consommation de masse': {
  'af': "Ford soutient que la production de masse n'est viable que si elle rencontre une consommation de masse, et que la chaîne de montage doit donc être complétée par des salaires élevés. La thèse articule trois éléments qui forment un système cohérent. La chaîne de montage déplace le produit devant l'ouvrier fixe, ce qui impose la cadence par le convoyeur lui-même plutôt que par la prescription, et supprime les temps de déplacement. La standardisation du produit permet d'allonger les séries et d'écraser les coûts unitaires grâce aux économies d'échelle. Le doublement du salaire journalier, enfin, remplit deux fonctions que l'on confond souvent : réduire une rotation du personnel devenue intenable face à la monotonie du travail, et solvabiliser une clientèle capable d'acheter la production. C'est le bouclage entre productivité, salaires et consommation qui constitue le cœur du régime fordiste.",
  'po': "Dans le chapitre, le fordisme constitue le modèle productif de référence du XXᵉ siècle et le mécanisme par lequel les gains de productivité se diffusent en pouvoir d'achat. Il fournit le cas d'école du régime d'accumulation analysé par l'école de la régulation, et le point de comparaison à partir duquel on mesurera la rupture toyotiste.",
  'co': "Le fordisme associe chaîne de montage, standardisation et salaires élevés : la cadence est imposée par le convoyeur, les économies d'échelle écrasent les coûts unitaires, et le salaire élevé réduit la rotation du personnel tout en solvabilisant la demande, bouclant ainsi productivité, salaires et consommation.",
 },
 'Toyotisme : juste-à-temps et qualité totale': {
  'af': "Ohno soutient que la performance productive ne provient pas de la taille des séries mais de l'élimination des gaspillages : il faut produire exactement ce qui est demandé, au moment où il est demandé, avec une qualité obtenue du premier coup. La thèse inverse le sens du flux. Au lieu de pousser la production vers l'aval selon des prévisions, chaque poste tire du poste amont ce dont il a besoin, ce qui supprime les stocks intermédiaires. Cette suppression a une conséquence décisive et voulue : les stocks ne masquant plus les défauts, tout incident arrête immédiatement la chaîne, de sorte que la qualité devient une contrainte absolue intégrée à la production au lieu d'être contrôlée après coup. L'opérateur reçoit alors le droit d'arrêter la ligne et la responsabilité de l'amélioration continue, ce qui réintègre une part de conception dans l'exécution. La contrepartie est une vulnérabilité : sans stock tampon, toute rupture d'approvisionnement paralyse la production.",
  'po': "Dans le chapitre, le toyotisme constitue la rupture avec le modèle fordiste et montre que l'organisation du travail évolue avec les contraintes de marché : la variété et la réactivité remplacent la standardisation lorsque la demande se diversifie. Il fournit en outre la clé de compréhension de la fragilité des chaînes de valeur mondiales étudiées en deuxième année.",
  'co': "Le toyotisme de Taiichi Ohno repose sur le flux tiré et le juste-à-temps : la suppression des stocks rend tout défaut immédiatement visible et impose une qualité obtenue du premier coup, au prix d'une vulnérabilité aux ruptures d'approvisionnement.",
 },
 'Bureaucratie et domination rationnelle-légale': {
  'ti': 'Les trois types de domination légitime',
  'af': "Weber soutient que toute autorité repose sur une croyance en sa légitimité, et il distingue trois types purs selon le fondement de cette croyance. La domination traditionnelle s'appuie sur le caractère sacré de coutumes immémoriales : on obéit parce qu'il en a toujours été ainsi. La domination charismatique s'appuie sur les qualités extraordinaires attribuées à une personne : on obéit à un individu en raison de ce qu'il est. La domination rationnelle-légale s'appuie sur la croyance en la validité de règles établies : on obéit à une fonction et non à une personne, dans les limites fixées par la règle. La thèse n'est pas que ces types se succèdent mécaniquement, mais que la modernité est caractérisée par la prédominance croissante du troisième. L'intérêt du modèle pour l'analyse de l'entreprise est qu'il éclaire la succession du fondateur charismatique par le dirigeant recruté sur diplôme et agissant selon des procédures.",
  'po': "Dans le chapitre, cette typologie fournit l'instrument d'analyse de l'autorité dans l'entreprise et permet de penser la professionnalisation de la direction. Elle articule l'étude de l'entrepreneur schumpétérien et celle du manager salarié, en montrant que le passage de l'un à l'autre est un changement de type de légitimité et non seulement de personne.",
  'co': "Max Weber distingue trois types de domination légitime — traditionnelle, charismatique et rationnelle-légale — et montre que la modernité est caractérisée par la prédominance de la troisième, où l'on obéit à une fonction définie par des règles et non à une personne.",
 },
 "Le mythe de l'entrepreneur": {
  'af': "Galluzzo soutient que la figure du fondateur génial est une construction idéologique, qui attribue à un individu ce qui résulte d'un travail collectif, de financements publics et de circonstances favorables, et dont la fonction sociale est de légitimer une répartition inégale des revenus et du pouvoir. La thèse procède par identification des opérations du récit entrepreneurial. Il isole un individu d'un collectif d'ingénieurs, de salariés et de chercheurs. Il efface l'amont public : recherche financée sur fonds publics, infrastructures, formation de la main-d'œuvre. Il invoque une vision là où l'observation montre surtout des itérations, des réorientations et des échecs. Il sélectionne enfin les survivants, en ne racontant que les réussites, ce qui donne à des trajectoires largement contingentes l'apparence d'une loi. Galluzzo en tire la conclusion politique : si la valeur vient d'un homme, sa rémunération et son pouvoir paraissent mérités.",
  'po': "Dans le chapitre, cette analyse déconstruit la figure placée au centre par Schumpeter et montre que la question « qui dirige l'entreprise ? » comporte une dimension idéologique. Elle fournit la critique sociologique du discours entrepreneurial, dont Mazzucato apportera plus tard la démonstration économique.",
  'co': "Anthony Galluzzo analyse le mythe de l'entrepreneur comme une construction idéologique : en isolant un individu d'un collectif et en effaçant l'amont public de l'innovation, le récit entrepreneurial légitime une répartition inégale des revenus et du pouvoir.",
 },
 'Fonctions administratives et professionnalisation de la direction': {
  'af': "Fayol soutient que diriger constitue un métier distinct, susceptible d'être analysé et enseigné, et il en décompose l'activité en cinq fonctions : prévoir, organiser, commander, coordonner, contrôler. La thèse opère un déplacement symétrique de celui de Taylor : là où Taylor rationalise l'exécution, Fayol rationalise la direction. Il montre que l'activité administrative est une fonction au même titre que la production ou la vente, qu'elle devient prépondérante à mesure que l'on s'élève dans la hiérarchie, et qu'elle obéit à des principes énonçables — unité de commandement, unité de direction, hiérarchie, division du travail. La conséquence historique de cette thèse est considérable et souvent sous-estimée : si diriger est une technique transmissible, alors la direction peut être exercée par un salarié formé plutôt que par le propriétaire du capital, ce qui ouvre la voie à la direction professionnelle.",
  'po': "Dans le chapitre, cette analyse fournit le chaînon manquant entre le propriétaire-entrepreneur et le manager salarié : elle explique pourquoi la séparation de la propriété et du contrôle décrite par Berle et Means devient possible. Elle montre également que la création des écoles de gestion procède directement de cette thèse.",
  'co': "Henri Fayol décompose l'activité de direction en cinq fonctions — prévoir, organiser, commander, coordonner, contrôler — et établit ainsi que diriger est une technique enseignable, ce qui rend possible l'exercice de la direction par un salarié formé plutôt que par le propriétaire du capital.",
 },
 'Séparation de la propriété et du contrôle': {
  'af': "Berle soutient que dans la grande entreprise moderne le capital est si dispersé entre de nombreux petits actionnaires que ceux-ci, propriétaires en droit, ne contrôlent plus l'entreprise : le pouvoir effectif appartient aux dirigeants. La thèse repose sur un problème d'action collective. Un actionnaire détenant une fraction infime du capital n'a aucun intérêt à engager le coût d'une surveillance dont le bénéfice serait partagé par tous les autres ; il préfère vendre ses titres si la gestion le mécontente, ce qu'on appelle voter avec ses pieds. Les dirigeants, eux, maîtrisent l'information, l'ordre du jour des assemblées et la composition du conseil. Le droit de propriété se vide ainsi de son contenu de contrôle, et les dirigeants peuvent poursuivre des objectifs propres — croissance, prestige, sécurité de l'emploi — distincts de la maximisation du profit que la théorie leur prête.",
  'po': "Dans le chapitre, cette thèse constitue le tournant de l'analyse du pouvoir dans l'entreprise : elle établit que la firme n'est pas un agent unique poursuivant le profit mais une organisation traversée par des intérêts divergents. Elle ouvre la séquence qui conduira à Galbraith puis, en réaction, à la gouvernance actionnariale.",
  'co': "Berle et Means établissent en 1932 la séparation de la propriété et du contrôle : la dispersion du capital prive chaque actionnaire de l'intérêt à surveiller la direction, de sorte que le pouvoir effectif revient aux dirigeants, libres de poursuivre des objectifs distincts de la maximisation du profit.",
 },
 'Capital dispersé et pouvoir managérial': {
  'af': "Means soutient que la dispersion du capital n'est pas un accident mais une tendance structurelle de la grande entreprise, et il en tire une conséquence macroéconomique originale : la formation des prix s'en trouve modifiée. L'apport propre de Means est double. Il est d'abord empirique : en recensant la structure de l'actionnariat des plus grandes sociétés américaines, il établit que dans une large part d'entre elles aucun actionnaire ni groupe ne détient une participation permettant le contrôle. Il est ensuite théorique : ces entreprises, soustraites à la discipline de l'actionnaire comme à celle d'un marché atomistique, fixent leurs prix par décision administrative plutôt que par ajustement instantané à l'offre et à la demande. Means nomme ces prix administrés et montre qu'ils sont rigides à la baisse, ce qui modifie profondément la dynamique macroéconomique en période de récession.",
  'po': "Dans le chapitre, cette analyse apporte la vérification empirique de la thèse de Berle et en tire une conséquence sur le fonctionnement des marchés : la grande entreprise ne subit pas le prix, elle le fixe. Elle fait ainsi le lien entre la question de la gouvernance et celle de la concurrence imparfaite étudiée au chapitre suivant.",
  'co': "Gardiner Means établit empiriquement la dispersion du capital des grandes sociétés et en déduit la notion de prix administrés : soustraites à la discipline de l'actionnaire comme du marché atomistique, ces entreprises fixent leurs prix par décision, avec une forte rigidité à la baisse.",
 },
 'Technostructure et pouvoir des experts': {
  'af': "Galbraith soutient que dans la grande entreprise moderne le pouvoir n'appartient ni aux actionnaires ni même au dirigeant pris isolément, mais à la technostructure : le groupe de cadres, d'ingénieurs et d'experts qui détient l'information nécessaire à la décision. La thèse s'appuie sur une contrainte cognitive : les décisions de la grande entreprise exigent des compétences si spécialisées qu'aucun individu ne les réunit, de sorte que la décision devient nécessairement collective et que le pouvoir suit l'information plutôt que le titre. La technostructure poursuit alors ses objectifs propres — croissance, stabilité, sécurité, autonomie — plutôt que le profit maximal, car la croissance accroît son importance tandis qu'un profit distribué aux actionnaires ne lui rapporte rien. Ayant besoin de prévisibilité, elle cherche enfin à maîtriser son environnement : fidéliser la demande par la publicité, sécuriser ses approvisionnements, négocier avec l'État. Galbraith nomme filière inversée ce renversement par lequel le producteur façonne les besoins.",
  'po': "Dans le chapitre, cette analyse pousse à son terme la logique ouverte par Berle et Means et met en cause deux hypothèses fondamentales : la maximisation du profit et la souveraineté du consommateur. Elle fournit la cible explicite contre laquelle la théorie de l'agence et la doctrine actionnariale se construiront.",
  'co': "John Kenneth Galbraith montre que le pouvoir dans la grande entreprise appartient à la technostructure, groupe d'experts détenant l'information nécessaire à la décision : celle-ci privilégie la croissance et la sécurité sur le profit, et façonne la demande par la publicité selon une filière inversée.",
 },
 'La main visible des managers': {
  'af': "Chandler soutient que la grande entreprise moderne s'est imposée parce que la coordination administrative par des managers salariés s'est révélée plus efficace que la coordination par le marché : à la main invisible de Smith répond la main visible de la hiérarchie. La thèse relie technologie, marché et organisation. Les techniques de production de masse et les transports rapides permettent des débits élevés, mais ce débit n'est rentable que si les flux sont régulés en continu, de l'approvisionnement à la distribution. Le marché, trop lent et trop incertain pour assurer cette régulation, est alors remplacé : l'entreprise intègre verticalement et crée une hiérarchie de managers chargés de planifier les flux. La croissance de taille engendre ensuite un problème de structure, que Chandler voit résolu par la forme multidivisionnelle, où une direction générale arbitre l'allocation du capital entre divisions autonomes — d'où sa formule selon laquelle la structure suit la stratégie.",
  'po': "Dans le chapitre, cette analyse fournit l'explication historique de l'émergence de la grande entreprise et introduit l'arbitrage entre marché et organisation qui structurera tout le chapitre suivant. Elle montre que la firme n'est pas un donné mais une réponse à des conditions techniques et commerciales déterminées.",
  'co': "Alfred Chandler explique l'essor de la grande entreprise par la supériorité de la coordination administrative sur la coordination par le marché : les débits élevés exigeant une régulation continue des flux, l'intégration verticale et la hiérarchie de managers remplacent le marché — la structure suivant la stratégie.",
 },
 "Théorie de l'agence et gouvernance actionnariale": {
  'af': "Jensen soutient que la relation entre actionnaires et dirigeants constitue une relation d'agence porteuse de conflits d'intérêts et de coûts, et que la gouvernance doit être conçue pour aligner les intérêts du dirigeant sur ceux des actionnaires. La thèse pose un cadre général : un principal délègue à un agent qui dispose d'une information supérieure et poursuit ses propres objectifs — avantages en nature, croissance excessive, prudence excessive, enracinement dans la fonction. Il en résulte trois types de coûts : les coûts de surveillance supportés par le principal, les coûts d'engagement que l'agent consent pour se rendre crédible, et une perte résiduelle irréductible. Les remèdes découlent du diagnostic : rémunération en actions et en options, administrateurs indépendants, endettement qui discipline en absorbant la trésorerie disponible, menace d'offre publique hostile. L'entreprise est alors conçue comme un nœud de contrats plutôt que comme une institution.",
  'po': "Dans le chapitre, cette théorie constitue la réponse à Berle, Means et Galbraith : si le pouvoir managérial est un problème, il faut le contraindre. Elle fournit le fondement théorique de la financiarisation de l'entreprise et de la doctrine de la valeur actionnariale, dont le chapitre examinera ensuite les critiques.",
  'co': "La théorie de l'agence de Jensen et Meckling analyse la relation actionnaires-dirigeants comme une délégation génératrice de coûts — surveillance, engagement, perte résiduelle — qu'il faut réduire par des dispositifs incitatifs : rémunération en actions, administrateurs indépendants, endettement disciplinant.",
 },
 "Coûts d'agence et architecture des incitations": {
  'af': "Meckling soutient que l'organisation de l'entreprise s'explique par la recherche d'une structure de contrats et d'incitations minimisant les coûts d'agence, et il insiste sur le caractère irréductible de ces coûts. La thèse souligne un arbitrage que la version simplifiée de la théorie néglige : la surveillance parfaite serait prohibitive et l'incitation parfaite est impossible, puisque le résultat dépend aussi d'aléas extérieurs à l'agent, de sorte qu'une rémunération entièrement indexée sur le résultat ferait supporter à celui-ci un risque qu'il n'accepterait pas sans compensation. Il faut donc arbitrer entre surveiller et inciter. Meckling montre en outre que la structure financière elle-même est un instrument de gouvernance : la dette contraint à dégager régulièrement de la trésorerie, les fonds propres laissent de la latitude. La structure observée résulte de cet arbitrage et non d'un optimum sans coût.",
  'po': "Dans le chapitre, cette précision empêche de lire la théorie de l'agence comme la description d'une solution : elle décrit un arbitrage permanent dont aucune configuration ne sort indemne. Elle relie en outre gouvernance et financement, ce qui prépare l'analyse de la financiarisation.",
  'co': "William Meckling souligne que les coûts d'agence sont irréductibles : la surveillance parfaite est prohibitive et l'incitation parfaite reporterait sur l'agent un risque qu'il refuserait, de sorte que la structure financière elle-même — dette contraignante contre fonds propres permissifs — devient un instrument de gouvernance.",
 },
 "La responsabilité de l'entreprise est d'accroître ses profits": {
  'af': "Friedman soutient que la seule responsabilité sociale de l'entreprise est d'accroître ses profits dans le respect des règles du jeu, et que le dirigeant qui engage les fonds des actionnaires dans des objectifs sociaux lève en réalité un impôt sans mandat. La thèse repose sur deux arguments distincts qu'il importe de ne pas confondre. L'argument de mandat : le dirigeant est l'agent des actionnaires et dispose de fonds qui ne sont pas les siens ; décider seul de les affecter à une cause revient à prélever et à dépenser sans légitimité démocratique. L'argument d'efficacité : définir l'intérêt général et poursuivre des objectifs sociaux relèvent du législateur, comptable devant les électeurs, tandis que l'entreprise est compétente pour produire efficacement. Friedman défend donc une division du travail entre marché et politique, et non une indifférence aux conséquences sociales de l'activité économique.",
  'po': "Dans le chapitre, cette position fournit la formulation la plus rigoureuse de la doctrine actionnariale et le point de départ nécessaire de tout débat sur la responsabilité sociale de l'entreprise. Elle doit être exposée dans sa logique propre avant d'être discutée, faute de quoi la critique de la gouvernance partenariale porte à vide.",
  'co': "Pour Milton Friedman, la responsabilité sociale de l'entreprise est d'accroître ses profits dans le respect des règles : engager les fonds des actionnaires dans des objectifs sociaux revient à lever un impôt sans mandat et à substituer le jugement du dirigeant à celui du législateur.",
 },
 'IA et emploi : tâches plutôt que métiers': {
  'af': "Autor soutient que l'intelligence artificielle ne supprime pas des métiers mais recompose des tâches, et que l'effet sur l'emploi dépend de la part de tâches automatisables dans chaque métier ainsi que de la capacité de la technologie à compléter plutôt qu'à remplacer. La thèse part d'une décomposition : un métier est un panier de tâches. L'automatisation d'une partie d'entre elles réduit le temps requis, ce qui peut accroître la demande du métier si la baisse du coût élargit le marché, ou la réduire si la tâche automatisée en constituait l'essentiel. L'intelligence artificielle déplace la frontière de ce qui est automatisable : elle atteint désormais des tâches cognitives non routinières — rédiger, coder, diagnostiquer — jusque-là protégées. Mais elle peut aussi élever la productivité des travailleurs les moins expérimentés et réduire la dispersion des performances, avec un effet égalisateur. La direction du résultat n'est donc pas technique mais dépend des usages et des institutions.",
  'po': "Dans le chapitre, cette analyse conclut l'étude des transformations du travail en montrant que la question de l'intelligence artificielle doit être traitée avec les mêmes outils que les vagues technologiques antérieures. Elle impose une méthode — raisonner en tâches — qui évite les prédictions globales invérifiables.",
  'co': "David Autor montre que l'intelligence artificielle recompose des tâches plutôt qu'elle ne supprime des métiers : en atteignant des tâches cognitives non routinières jusque-là protégées, elle peut se substituer au travail qualifié comme le compléter, selon les usages et les institutions.",
 },
 'Financiarisation, plateformes et pluralité des capitalismes': {
  'ti': 'Financiarisation et transformation de la gouvernance',
  'af': "Plihon soutient que la financiarisation donne la primauté aux exigences de rentabilité des investisseurs et transforme en profondeur le fonctionnement de l'entreprise. La thèse identifie trois effets solidaires. Premièrement, un raccourcissement de l'horizon des décisions : l'entreprise cotée est évaluée à chaque publication trimestrielle, ce qui pénalise les investissements dont le rendement est différé. Deuxièmement, une réallocation des flux de trésorerie : les rachats d'actions et les dividendes se substituent partiellement à l'investissement productif, parce qu'ils soutiennent directement le cours. Troisièmement, un transfert du risque vers les salariés : l'exigence de rentabilité stable conduit à faire porter l'ajustement conjoncturel par l'emploi et les conditions de travail plutôt que par la rémunération du capital. La financiarisation n'est donc pas un simple mode de financement mais une transformation du rapport entre l'entreprise et ses parties prenantes.",
  'po': "Dans le chapitre, cette analyse montre les effets concrets de la gouvernance actionnariale théorisée par Jensen et Friedman, et permet d'en évaluer les conséquences au-delà de ses justifications. Elle fournit le contenu empirique du retour du pouvoir actionnarial que les 3D de Bourguinat ont rendu possible.",
  'co': "David Plihon montre que la financiarisation raccourcit l'horizon des décisions, substitue partiellement rachats d'actions et dividendes à l'investissement productif et transfère le risque conjoncturel vers les salariés : elle transforme ainsi le rapport entre l'entreprise et ses parties prenantes.",
 },
 'Les 3D de la globalisation financière': {
  'af': "Bourguinat soutient que la transformation de la finance depuis les années 1980 se résume à trois mouvements solidaires : la désintermédiation, le décloisonnement et la déréglementation. La désintermédiation fait passer le financement du crédit bancaire au marché : l'entreprise émet directement titres et obligations, ce qui la soumet au jugement permanent des investisseurs au lieu de la relation durable avec un banquier. Le décloisonnement supprime les frontières entre compartiments — court et long terme, national et international, banque et assurance — de sorte que les capitaux circulent instantanément d'un marché à l'autre. La déréglementation lève les contrôles des changes et les encadrements du crédit. La thèse est que ces trois mouvements se renforcent mutuellement : ils accroissent la liquidité et abaissent le coût du capital, mais ils propagent aussi les chocs d'un marché à l'autre et confèrent aux investisseurs un pouvoir direct sur la gestion des entreprises.",
  'po': "Dans le chapitre, cette grille fournit l'explication historique du retour du pouvoir actionnarial : elle montre que la gouvernance actionnariale n'a pas seulement été théorisée, elle a été rendue praticable par une transformation des marchés. Elle relie ainsi l'analyse de l'entreprise à celle du système financier.",
  'co': "Henri Bourguinat résume la globalisation financière par les trois D — désintermédiation, décloisonnement, déréglementation : en soumettant l'entreprise au jugement permanent des marchés et en faisant circuler les capitaux sans frontière, ces mouvements abaissent le coût du capital mais propagent les chocs.",
 },
 'Les trois âges du capitalisme': {
  'af': "La périodisation en trois âges — l'âge du commerce, l'âge de l'usine et l'âge de la finance — propose de distinguer les régimes du capitalisme selon le lieu où se forme le profit dominant. Dans l'âge du commerce, le profit provient de l'échange à distance et du contrôle des routes et des comptoirs ; le capital y est marchand et circulant, et la richesse se constitue par l'écart entre deux marchés. Dans l'âge de l'usine, il provient de la production et des gains de productivité ; le capital devient fixe et industriel, et le rapport salarial s'institutionnalise. Dans l'âge de la finance, il provient de la valorisation des actifs et de l'allocation du capital ; la liquidité et la rentabilité financière deviennent les critères dominants. La portée de cette distinction est celle d'un instrument de mise en perspective : elle permet de situer la financiarisation contemporaine dans une histoire longue plutôt que de la traiter comme une nouveauté absolue.",
  'po': "Dans le chapitre, cette périodisation fournit un repère chronologique commode pour organiser l'étude des transformations du capitalisme. Les documents d'Écosphère la mentionnent sans en préciser davantage la référence : il convient donc de l'utiliser comme repère de périodisation plutôt que comme autorité théorique, et de lui préférer l'analyse régulationniste lorsqu'une démonstration est requise.",
  'co': "La distinction des trois âges du capitalisme — commerce, usine, finance — permet de situer la financiarisation contemporaine dans une histoire longue : le profit dominant se forme successivement dans l'échange à distance, dans la production, puis dans la valorisation des actifs.",
 },
}

SPLIT[8] = [
 ('Max Weber', 'La bureaucratie et le processus de rationalisation', {
  'affirme': "Weber soutient que la bureaucratie constitue la forme d'organisation la plus techniquement efficace jamais conçue, et que son développement participe d'un processus plus vaste de rationalisation du monde moderne dont il mesure aussi le prix. La bureaucratie se définit par un ensemble de traits solidaires : compétences délimitées par des règles écrites, hiérarchie des fonctions, recrutement et promotion sur critères impersonnels, séparation stricte de la fonction et de la personne, traces écrites des décisions. Sa supériorité tient à la prévisibilité et à l'égalité de traitement, qui rendent l'action administrative calculable — propriété indispensable à l'activité économique moderne. Mais Weber décrit aussi le revers : l'obéissance à la règle peut devenir une fin en soi, l'organisation perd de vue ses finalités et enferme ses membres dans ce qu'il appelle une cage d'acier. La rationalisation n'est donc pas un progrès univoque.",
  'mecanisme': "Le raisonnement s'organise en trois temps. Premièrement, la bureaucratie est supérieure en efficacité technique parce qu'elle élimine l'arbitraire : des règles écrites et une compétence définie rendent la décision prévisible, donc anticipable par les agents économiques, ce qui abaisse l'incertitude et autorise le calcul. Deuxièmement, cette prévisibilité a un coût : elle suppose que les cas soient traités selon la règle et non selon leur singularité, ce qui produit nécessairement des décisions inadaptées lorsque la situation n'avait pas été prévue. Troisièmement, l'organisation développe une tendance à la conservation : les agents sont évalués sur le respect de la procédure, de sorte qu'il devient rationnel pour eux d'appliquer la règle même lorsqu'elle manque son objet. La rationalité formelle, qui porte sur les moyens, se dissocie ainsi de la rationalité matérielle, qui porterait sur les fins.",
  'exemple': "Un service qui applique strictement une procédure alors que son application produit un résultat manifestement contraire à l'objectif poursuivi illustre le basculement de la rationalité en formalisme : l'agent n'est pas incompétent, il est rationnel au regard des critères sur lesquels il est jugé.",
  'diss': "Référence centrale sur « l'organisation est-elle rationnelle ? », « la bureaucratie est-elle efficace ? », « comment s'exerce l'autorité dans l'entreprise ? ». Place : première partie pour exposer le modèle, avant que Crozier n'en montre les dysfonctionnements réels et Morel les décisions absurdes qu'il engendre.",
  'portee': "Dans le chapitre, cette analyse fournit le modèle d'organisation de la grande entreprise moderne et explique pourquoi la direction professionnelle a pu s'y substituer au fondateur. Elle introduit la notion de rationalisation, qui permet de relier l'organisation du travail chez Taylor, l'administration chez Fayol et la technostructure chez Galbraith.",
  'copie': "Max Weber décrit la bureaucratie comme la forme d'organisation la plus efficace techniquement — règles écrites, compétences délimitées, impersonnalité, hiérarchie — tout en soulignant que la rationalité formelle peut se dissocier des fins poursuivies et enfermer l'organisation dans une cage d'acier.",
  'ouvrage': "Économie et société (1922)",
  'notions': ['bureaucratie', 'rationalisation', 'cage d\'acier', 'impersonnalité', 'organisation'],
  'liens': [('Michel Crozier', 'opposition', "Crozier montre que la bureaucratie réelle est traversée par des jeux de pouvoir que la règle ne prévoit pas."),
            ('Henri Fayol', 'complement', "Fayol décrit de l'intérieur les fonctions administratives de cette organisation rationnelle."),
            ('Frederick Taylor', 'complement', "L'organisation scientifique du travail est l'application du même mouvement de rationalisation à l'exécution.")],
 }),
 ('Daron Acemoglu', "La direction du progrès technique n'est pas neutre", {
  'affirme': "Acemoglu soutient que les institutions et les incitations ne déterminent pas seulement le volume d'innovation mais sa direction, et que le choix entre une technique qui complète le travail et une technique qui le remplace relève d'une décision collective et non d'une nécessité technique. La thèse conteste frontalement le déterminisme technologique selon lequel une technologie s'imposerait par sa seule supériorité. À innovation donnée, la recherche peut être orientée vers l'automatisation, qui substitue le capital au travail, ou vers l'augmentation des capacités humaines, qui élève la productivité du travailleur. Ce qui oriente ce choix n'est pas la technique mais un ensemble de signaux économiques et politiques : la fiscalité relative du capital et du travail, le rapport de force syndical, les priorités de la recherche publique, le discours dominant sur l'avenir du travail. Une fiscalité favorable au capital pousse ainsi vers l'automatisation, y compris lorsque celle-ci n'apporte qu'un gain de productivité médiocre.",
  'mecanisme': "Le raisonnement procède en quatre étapes. Premièrement, l'innovation est une activité économique dont la direction résulte d'un calcul de rentabilité anticipée. Deuxièmement, cette rentabilité dépend du coût relatif des facteurs : si le capital est fiscalement avantagé et le travail chargé, automatiser devient rentable même pour un gain de productivité faible. Troisièmement, les effets sur l'emploi diffèrent radicalement selon la direction prise : une technologie qui complète le travail élève les salaires et la demande de travail, une technologie qui le remplace déplace le revenu vers le capital. Quatrièmement, puisque ces effets dépendent de paramètres que les politiques publiques fixent, la direction du progrès technique est un objet légitime de décision collective. Acemoglu introduit ainsi une distinction décisive entre automatisation excessive et automatisation productive.",
  'exemple': "Remplacer une caissière par une borne automatique peut n'apporter qu'un gain de productivité marginal tout en étant privément rentable, parce que le capital est fiscalement avantagé par rapport au travail : la technique est adoptée sans que le gain social le justifie.",
  'diss': "Référence contemporaine de haut niveau sur « le progrès technique est-il neutre ? », « faut-il orienter l'innovation ? », « l'intelligence artificielle menace-t-elle l'emploi ? ». Place : troisième partie, comme dépassement politique d'un débat habituellement posé en termes techniques.",
  'portee': "Dans le chapitre, cette thèse conclut l'analyse du progrès technique en montrant que ses effets sur l'emploi ne sont pas subis mais résultent de choix antérieurs. Elle articule les institutions, l'innovation et le travail, c'est-à-dire les trois objets du chapitre, et fournit la grille d'analyse la plus solide pour traiter l'intelligence artificielle.",
  'copie': "Daron Acemoglu montre que la direction du progrès technique n'est pas neutre : le choix entre une technologie qui complète le travail et une technologie qui le remplace dépend du coût relatif des facteurs, de la fiscalité et des priorités de recherche, et relève donc d'une décision collective.",
  'ouvrage': "Why Nations Fail (2012)",
  'notions': ['direction du progrès technique', 'automatisation', 'complémentarité', 'fiscalité du capital', 'IA'],
  'liens': [('David Autor', 'complement', "L'approche par tâches fournit le cadre d'analyse des choix d'automatisation."),
            ('Robert Allen', 'prolonge', "Allen avait montré que les prix relatifs commandent l'adoption des techniques ; Acemoglu montre qu'ils en commandent aussi la direction."),
            ('Mariana Mazzucato', 'complement', "Si l'État finance l'amont de l'innovation, il peut aussi en orienter la direction.")],
 }),
 ('Joseph Schumpeter', "Routinisation de l'innovation et avenir du capitalisme", {
  'affirme': "Schumpeter soutient que le capitalisme est menacé non par ses échecs mais par ses succès : la grande entreprise bureaucratisée routinise l'innovation et efface la figure de l'entrepreneur qui en constituait le ressort. La thèse décrit un retournement paradoxal. L'innovation, d'abord portée par des individus affrontant l'incertitude, devient l'affaire de départements de recherche organisés, dotés de budgets, de procédures et d'objectifs : elle se régularise et devient prévisible. Ce progrès organisationnel est réel, mais il supprime la fonction entrepreneuriale en tant que telle, et avec elle la justification sociale du profit et de la propriété. Schumpeter ajoute une dimension sociologique : le capitalisme engendre une classe d'intellectuels et de cadres qui, formés à l'esprit critique, contestent les fondements de l'ordre qui les a produits. L'affaiblissement du capitalisme viendrait donc de sa propre réussite, non d'une crise économique.",
  'mecanisme': "L'enchaînement comporte quatre maillons. Premièrement, la concurrence pousse les firmes à innover, donc à se doter de capacités de recherche permanentes. Deuxièmement, ces capacités exigent une taille et une organisation importantes, ce qui favorise la grande entreprise bureaucratisée. Troisièmement, l'innovation y devient une fonction administrée, prévisible et collective : elle ne requiert plus l'individu exceptionnel qui brisait la routine, mais des équipes appliquant des procédures. Quatrièmement, la figure de l'entrepreneur disparaissant, le profit et la propriété perdent leur justification fonctionnelle aux yeux de la société ; parallèlement, la classe instruite que le capitalisme a fait naître en conteste la légitimité. Le système se trouve ainsi privé de ses soutiens sociaux alors même que sa performance économique se maintient.",
  'exemple': "Le laboratoire de recherche intégré d'une grande firme, doté d'un budget pluriannuel et d'objectifs de dépôt de brevets, produit de l'innovation de manière régulière et administrée : l'entrepreneur schumpétérien y a cédé la place à une organisation.",
  'diss': "Référence forte en troisième partie des sujets « l'entrepreneur est-il irremplaçable ? », « la grande entreprise est-elle innovante ? », « le capitalisme est-il menacé ? ». Permet de conclure autrement que par la seule opposition entre crise et stabilité, en introduisant la question de la légitimité.",
  'portee': "Dans le chapitre, cette thèse relie l'analyse de l'innovation à celle du pouvoir dans l'entreprise : la routinisation qu'elle décrit est exactement ce que Berle, Means et Galbraith observent empiriquement. Elle offre la perspective la plus large du chapitre, en posant que la transformation de l'entreprise engage l'avenir du système économique lui-même.",
  'copie': "Schumpeter soutient que le capitalisme est menacé par ses succès : en confiant l'innovation à des départements de recherche organisés, la grande entreprise la routinise et efface la figure de l'entrepreneur, privant le profit et la propriété de leur justification fonctionnelle.",
  'ouvrage': "Capitalisme, socialisme et démocratie (1942)",
  'notions': ['routinisation', 'bureaucratisation', 'entrepreneur', 'légitimité', 'grande entreprise'],
  'liens': [('John Kenneth Galbraith', 'prolonge', "La technostructure est la forme achevée de la routinisation que Schumpeter annonçait."),
            ('Adolf Berle', 'complement', "La séparation de la propriété et du contrôle est le versant juridique du même mouvement."),
            ('Anthony Galluzzo', 'complement', "Si l'innovation est collective et organisée, le récit du fondateur génial devient une construction idéologique.")],
 }),
 ('David Plihon', 'Plateformes, travail et pluralité des capitalismes', {
  'affirme': "Plihon soutient que le capitalisme contemporain se caractérise par la montée des plateformes et par la coexistence de modèles nationaux distincts, de sorte qu'il n'existe pas un capitalisme mais des capitalismes. Les plateformes obéissent à une logique économique propre : les effets de réseau y engendrent des positions dominantes très rapidement, puisque l'utilité du service croît avec le nombre d'utilisateurs ; la valeur se déplace vers les données accumulées ; et le statut d'indépendant se substitue au salariat pour les travailleurs qui exécutent le service. La pluralité des capitalismes constitue le second volet de la thèse : les modèles anglo-saxon, rhénan, nordique, asiatique d'État et chinois diffèrent par leur rapport salarial, leur mode de financement et le rôle qu'ils assignent à l'État. Plihon souligne enfin que la responsabilité sociale de l'entreprise et la gouvernance hybride constituent des réponses à la contestation du modèle actionnarial, sans que leur portée effective soit acquise.",
  'mecanisme': "Trois mécanismes doivent être distingués. Le premier est l'effet de réseau : chaque utilisateur supplémentaire accroît la valeur du service pour tous les autres, ce qui favorise la concentration et rend l'entrée d'un concurrent très difficile une fois la masse critique atteinte. Le deuxième est le déplacement de la valeur vers les données : la plateforme ne possède souvent ni les véhicules, ni les logements, ni la force de travail, mais l'information qui permet d'apparier l'offre et la demande. Le troisième est la requalification du rapport de travail : en traitant l'exécutant comme un indépendant, la plateforme transfère sur lui le risque d'activité, les charges d'équipement et l'absence de protection, tout en conservant un contrôle algorithmique sur ses conditions d'exercice. La pluralité des capitalismes, enfin, tient à ce que chaque configuration nationale traite ces phénomènes différemment.",
  'exemple': "Une plateforme de livraison ne possède ni véhicules ni salariés mais détermine par algorithme les tarifs, l'attribution des courses et l'évaluation des livreurs : le contrôle s'exerce pleinement sans que le rapport soit juridiquement salarial.",
  'diss': "Référence contemporaine indispensable sur « le numérique transforme-t-il le travail ? », « existe-t-il un seul capitalisme ? », « faut-il réguler les plateformes ? ». Place : troisième partie, pour actualiser l'analyse de l'entreprise et du rapport salarial.",
  'portee': "Dans le chapitre, cette analyse prolonge l'étude des formes d'entreprise jusqu'aux plateformes et montre que le rapport salarial, dont le chapitre a retracé la formation avec l'usine, peut aussi se défaire. Elle relie transformations du capitalisme, du travail et de la gouvernance.",
  'copie': "David Plihon montre que les plateformes obéissent à une logique propre : les effets de réseau y engendrent des positions dominantes, la valeur se déplace vers les données, et la requalification de l'exécutant en indépendant transfère sur lui le risque tout en maintenant un contrôle algorithmique.",
  'ouvrage': "Les capitalismes contemporains (2025)",
  'notions': ['plateformes', 'effets de réseau', 'ubérisation', 'données', 'variétés du capitalisme'],
  'liens': [('Robert Boyer', 'complement', "La pluralité des capitalismes relève de la tradition régulationniste de la complémentarité institutionnelle."),
            ('Richard Arkwright', 'opposition', "L'usine avait concentré les travailleurs sous un même statut ; la plateforme les disperse en les maintenant sous contrôle."),
            ('Robert Castel', 'complement', "La requalification en indépendant prolonge la fragilisation de la société salariale.")],
 }),
]
